pub type AppError = Failed(String)

byres record FileHandle { fd: Int64 }

impl Releasable for FileHandle {
    fn release(mut self) {
        return
    }
}

pub fn readIt() -> Int64 {
    scope resource(f = FileHandle { fd: 3 }) {
        if f.fd > 0 {
            return f.fd
        }
    }
    return 0
}

pub fn main() -> Result<(), AppError> {
    return Ok(())
}

